import rfftf = require( './index' );

// TESTS //

// The function returns void...
{
	const c = new Float64Array( 4 );
	const workspace = new Float64Array( 50 );
	rfftf( 4, c, 1, 0, workspace, 1, 0 ); // $ExpectType void
}

// The compiler throws an error if the function is provided a sequence length which is not a number...
{
	const c = new Float64Array( 4 );
	const workspace = new Float64Array( 50 );

	rfftf( '4', c, 1, 0, workspace, 1, 0 ); // $ExpectError
	rfftf( true, c, 1, 0, workspace, 1, 0 ); // $ExpectError
	rfftf( false, c, 1, 0, workspace, 1, 0 ); // $ExpectError
	rfftf( null, c, 1, 0, workspace, 1, 0 ); // $ExpectError
	rfftf( undefined, c, 1, 0, workspace, 1, 0 ); // $ExpectError
	rfftf( [], c, 1, 0, workspace, 1, 0 ); // $ExpectError
	rfftf( {}, c, 1, 0, workspace, 1, 0 ); // $ExpectError
	rfftf( ( x: number ): number => x, c, 1, 0, workspace, 1, 0 ); // $ExpectError
}

// The compiler throws an error if the function is provided an input array which is not a Float64Array...
{
	const workspace = new Float64Array( 50 );

	rfftf( 4, '1,2,3,4', 1, 0, workspace, 1, 0 ); // $ExpectError
	rfftf( 4, 5, 1, 0, workspace, 1, 0 ); // $ExpectError
	rfftf( 4, true, 1, 0, workspace, 1, 0 ); // $ExpectError
	rfftf( 4, false, 1, 0, workspace, 1, 0 ); // $ExpectError
	rfftf( 4, null, 1, 0, workspace, 1, 0 ); // $ExpectError
	rfftf( 4, undefined, 1, 0, workspace, 1, 0 ); // $ExpectError
	rfftf( 4, [], 1, 0, workspace, 1, 0 ); // $ExpectError
	rfftf( 4, {}, 1, 0, workspace, 1, 0 ); // $ExpectError
	rfftf( 4, ( x: number ): number => x, 1, 0, workspace, 1, 0 ); // $ExpectError
}

// The compiler throws an error if the function is provided a stride for `c` which is not a number...
{
	const c = new Float64Array( 4 );
	const workspace = new Float64Array( 50 );

	rfftf( 4, c, '1', 0, workspace, 1, 0 ); // $ExpectError
	rfftf( 4, c, true, 0, workspace, 1, 0 ); // $ExpectError
	rfftf( 4, c, false, 0, workspace, 1, 0 ); // $ExpectError
	rfftf( 4, c, null, 0, workspace, 1, 0 ); // $ExpectError
	rfftf( 4, c, undefined, 0, workspace, 1, 0 ); // $ExpectError
	rfftf( 4, c, [], 0, workspace, 1, 0 ); // $ExpectError
	rfftf( 4, c, {}, 0, workspace, 1, 0 ); // $ExpectError
	rfftf( 4, c, ( x: number ): number => x, 0, workspace, 1, 0 ); // $ExpectError
}

// The compiler throws an error if the function is provided an offset for `c` which is not a number...
{
	const c = new Float64Array( 4 );
	const workspace = new Float64Array( 50 );

	rfftf( 4, c, 1, '0', workspace, 1, 0 ); // $ExpectError
	rfftf( 4, c, 1, true, workspace, 1, 0 ); // $ExpectError
	rfftf( 4, c, 1, false, workspace, 1, 0 ); // $ExpectError
	rfftf( 4, c, 1, null, workspace, 1, 0 ); // $ExpectError
	rfftf( 4, c, 1, undefined, workspace, 1, 0 ); // $ExpectError
	rfftf( 4, c, 1, [], workspace, 1, 0 ); // $ExpectError
	rfftf( 4, c, 1, {}, workspace, 1, 0 ); // $ExpectError
	rfftf( 4, c, 1, ( x: number ): number => x, workspace, 1, 0 ); // $ExpectError
}

// The compiler throws an error if the function is provided a workspace which is not a Float64Array...
{
	const c = new Float64Array( 4 );

	rfftf( 4, c, 1, 0, '4,2,3,5', 1, 0 ); // $ExpectError
	rfftf( 4, c, 1, 0, 5, 1, 0 ); // $ExpectError
	rfftf( 4, c, 1, 0, true, 1, 0 ); // $ExpectError
	rfftf( 4, c, 1, 0, false, 1, 0 ); // $ExpectError
	rfftf( 4, c, 1, 0, null, 1, 0 ); // $ExpectError
	rfftf( 4, c, 1, 0, undefined, 1, 0 ); // $ExpectError
	rfftf( 4, c, 1, 0, [], 1, 0 ); // $ExpectError
	rfftf( 4, c, 1, 0, {}, 1, 0 ); // $ExpectError
	rfftf( 4, c, 1, 0, ( x: number ): number => x, 1, 0 ); // $ExpectError
}

// The compiler throws an error if the function is provided a stride for workspace which is not a number...
{
	const c = new Float64Array( 4 );
	const workspace = new Float64Array( 50 );

	rfftf( 4, c, 1, 0, workspace, '1', 0 ); // $ExpectError
	rfftf( 4, c, 1, 0, workspace, true, 0 ); // $ExpectError
	rfftf( 4, c, 1, 0, workspace, false, 0 ); // $ExpectError
	rfftf( 4, c, 1, 0, workspace, null, 0 ); // $ExpectError
	rfftf( 4, c, 1, 0, workspace, undefined, 0 ); // $ExpectError
	rfftf( 4, c, 1, 0, workspace, [], 0 ); // $ExpectError
	rfftf( 4, c, 1, 0, workspace, {}, 0 ); // $ExpectError
	rfftf( 4, c, 1, 0, workspace, ( x: number ): number => x, 0 ); // $ExpectError
}

// The compiler throws an error if the function is provided an offset for workspace which is not a number...
{
	const c = new Float64Array( 4 );
	const workspace = new Float64Array( 50 );

	rfftf( 4, c, 1, 0, workspace, 1, '0' ); // $ExpectError
	rfftf( 4, c, 1, 0, workspace, 1, true ); // $ExpectError
	rfftf( 4, c, 1, 0, workspace, 1, false ); // $ExpectError
	rfftf( 4, c, 1, 0, workspace, 1, null ); // $ExpectError
	rfftf( 4, c, 1, 0, workspace, 1, undefined ); // $ExpectError
	rfftf( 4, c, 1, 0, workspace, 1, [] ); // $ExpectError
	rfftf( 4, c, 1, 0, workspace, 1, {} ); // $ExpectError
	rfftf( 4, c, 1, 0, workspace, 1, ( x: number ): number => x ); // $ExpectError
}

// The compiler throws an error if the function is provided an unsupported number of arguments...
{
	const c = new Float64Array( 4 );
	const workspace = new Float64Array( 50 );

	rfftf(); // $ExpectError
	rfftf( 4 ); // $ExpectError
	rfftf( 4, c ); // $ExpectError
	rfftf( 4, c, 1 ); // $ExpectError
	rfftf( 4, c, 1, 0 ); // $ExpectError
	rfftf( 4, c, 1, 0, workspace ); // $ExpectError
	rfftf( 4, c, 1, 0, workspace, 1 ); // $ExpectError
	rfftf( 4, c, 1, 0, workspace, 1, 0, 123 ); // $ExpectError
}
